  "implementation": "def solve(case):
    payload = case.get('payload', case)
    tokens = list(payload['tokens'])
    calls = payload['calls']
    if not isinstance(tokens, list) or not isinstance(calls, list):
        raise ValueError('Invalid case structure')
    for call in calls:
        required = ('call_id','start','end','score','replacement_tokens')
        if not all(k in call for k in required):
            raise ValueError('Missing field in call')
        if not isinstance(call['start'], int) or not isinstance(call['end'], int):
            raise ValueError('start/end must be ints')
        if call['start'] < 0 or call['end'] > len(tokens) or call['start'] > call['end']:
            raise ValueError('Invalid interval')
    sorted_calls = sorted(calls, key=lambda c: (-c['score'], c['start'], c['call_id']))
    selected = []
    for call in sorted_calls:
        s, e = call['start'], call['end']
        overlap = False
        for sel in selected:
            if max(s, sel['start']) < min(e, sel['end']):
                overlap = True
                break
        if not overlap:
            selected.append(call)
    selected_by_start = sorted(selected, key=lambda c: c['start'])
    selected_ids = [c['call_id'] for c in selected_by_start]
    result_tokens = list(tokens)
    for call in sorted(selected, key=lambda c: -c['start']):
        s, e = call['start'], call['end']
        repl = call['replacement_tokens']
        result_tokens[s:e] = repl
    return {'selected_ids': selected_ids, 'tokens': result_tokens}"
}
